CREATE TABLE `calendars` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `per_date` date NOT NULL,
  `buddhist_year_my` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `buddhist_year_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_year_my` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_year_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_month_my` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_month_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_day_my` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_day_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_type_of_day_my` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_type_of_day_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_weekday_my` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `my_cal_weekday_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_date_of_tagu` date DEFAULT NULL,
  `first_date_of_waso` date DEFAULT NULL,
  `is_watat` tinyint(1) DEFAULT NULL,
  `is_big_watat` tinyint(1) DEFAULT NULL,
  `akyo_day` date DEFAULT NULL,
  `akya_day` date DEFAULT NULL,
  `first_akyat_day` date DEFAULT NULL,
  `second_akyat_day` date DEFAULT NULL,
  `atat_day` date DEFAULT NULL,
  `new_year_day` date DEFAULT NULL,
  `akya_time` datetime DEFAULT NULL,
  `atat_time` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `calendars_per_date_unique` (`per_date`)
) ENGINE=InnoDB AUTO_INCREMENT=47848 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
