INSERT INTO `resource_details` VALUES (1,1,'1','သင် ဒီနှစ်ထဲမှာ အိုးပိုင်၊ အိမ်ပိုင်မရှိသေးရင် အိုးပိုင်၊ အိမ်ပိုင်ရတတ်ပါတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(2,1,'1',' ဒါမှမဟုတ်ရင်လည်း အိမ်နေရာ ပြောင်းရွှေ့ရတတ်ပါတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(3,1,'1',' \r\nလုပ်ငန်းတိုးတက်ခြင်း၊ ရာထူးတိုးတက်ခြင်းမျိုး ကြုံတွေ့ရပါလိမ့်မယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(4,1,'1',' ခါတိုင်းနှစ်နဲ့မတူဘဲ သင်သည် သင့်ရဲ့ ပတ်ဝန်းကျင်မှာ တန်ခိုးဩဇာတွေ မြင့်တက်လာမယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(5,1,'1',' ကောင်းသော ဂုဏ်သတင်းတွေနဲ့ ကျော်ကြားလာမယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(6,1,'1',' ပျော်စရာကောင်းတဲ့ အလုပ်တွေကိုလည်း လုပ်ရပါလိမ့်မယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(7,1,'1',' ကိုယ်ပိုင်လုပ်ငန်းလုပ်တဲ့ လူဆိုလျှင် လုပ်ငန်းတွေ တိုးချဲ့ရပါလိမ့်မည်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(8,1,'1',' လုပ်ငန်းမှာ နေရာကောင်းတွေ ရတတ်ပါလိမ့်မယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(9,1,'1','\r\nဘုရားဖူးထွက်တာမျိုး၊ အလှူအတန်းကိစ္စအတွက် ခရီးထွက်တာမျိုး ကြုံရတတ်ပါတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(10,1,'1',' ရပ်ဝေးခရီး၊ နိုင်ငံခြားခရီး သွားရတာမျိုးလည်း ကြုံတွေ့ရတတ်ပါတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(11,1,'1','\r\nသင်ပိုင်သော ပစ္စည်းတွေကိုတော့ သတိထားပြီး သိမ်းဆည်းပါ',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(12,1,'1',' ဒီနှစ်မှာ သူခိုး ခိုးခံရတတ်ပါတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(13,1,'1',' အလုပ်အကိုင် ကောင်းတယ်ဆိုပေမယ့် အလုပ်မှာ အတိုက်အခံတော့ရှိတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(14,1,'1',' မိမိအထက်လူကြီးက မိမိအပေါ်မှာ အထင်လွဲတတ်ပါတယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(15,1,'1',' \r\nဘာပဲဖြစ်ဖြစ် ဒီလိုကံကောင်းတဲ့နှစ်မျိုးမှာ သူများလာအပ်တဲ့ ပစ္စည်းဟောင်းတွေ၊ အဖိုးမတန်တဲ့ ကျောက်မျက်ရတနာတွေကို လက်မခံသင့်ပါ',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(16,1,'1',' လက်ခံ လိုက်ပါက လာဘ်တိတ်သွားမယ်',0,'2023-06-30 07:57:41','2023-06-30 07:57:41'),(17,1,'1','\r\nရှင်သီဝလိပုံတော်တွေ၊ ဘုရားဆင်းတုတော