--
-- Table structure for table `resources`
--

DROP TABLE IF EXISTS `resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resources` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `weekday` int DEFAULT NULL COMMENT 'Sunday, Monday, etc',
  `category` int DEFAULT NULL COMMENT 'Love, Business, Edu, etc',
  `format` int DEFAULT NULL COMMENT 'Mahabote, Zodiac, etc',
  `lecture_type` int DEFAULT NULL COMMENT 'a day, a week, a month, a year, life-time',
  `by_year` int DEFAULT NULL COMMENT 'year',
  `by_month` int DEFAULT NULL COMMENT 'month',
  `by_date` int DEFAULT NULL COMMENT 'date',
  `modulus` int DEFAULT NULL COMMENT 'modulus by age or year',
  `thatyout_year` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'thatyout year',
  `mahabote` int DEFAULT NULL,
  `zodiac` int DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

